// 8dp is the maximum configurable column precision: rounding COMPUTED values there keeps
// every client-configured scale intact while killing float residue.
const q8 = (v) => Number((parseFloat(v) || 0).toFixed(8));
let allData = {{workflowparams:allData}};
const saveAs = {{workflowparams:saveAs}};
const pageStatus = {{workflowparams:pageStatus}};

// stock_movement is the persisted recovery table. Only its columns survive: the
// form also carries UI-only keys, and the client-side cleanup is not a boundary.
const LINE_FIELDS = [
  'id', 'item_selection', 'item_name', 'item_desc', 'requested_qty', 'bom_ratio',
  'total_quantity', 'quantity_uom', 'storage_location_id', 'location_id',
  'batch_number', 'manufacturing_date', 'expired_date', 'item_remark',
  'item_remark_2', 'item_remark_3', 'project_id', 'uom_options'
];

const lines = (allData.stock_movement || []).map(function (src, index) {
  const line = {};
  LINE_FIELDS.forEach(function (k) {
    if (src[k] !== undefined) line[k] = src[k];
  });
  line.requested_qty = q8(src.requested_qty);
  line.total_quantity = q8(src.total_quantity);
  // A null ratio marks a manually added row; rounding it would turn it into 0
  // and make the form rescale that row on the next quantity change.
  const ratio = src.bom_ratio;
  line.bom_ratio = ratio === null || ratio === undefined || ratio === '' ? null : q8(ratio);
  line.organization_id = allData.organization_id;
  line.issuing_plant = allData.issuing_operation_faci || null;
  line.line_index = index + 1;
  return line;
});
allData.stock_movement = lines;

// item_qty is decimal on the header -- the source quantity being disassembled.
allData.item_qty = q8(allData.item_qty);

const storedStatus = pageStatus === 'Add' ? 'Draft' : (allData.item_disassembly_status || 'Draft');
allData.item_disassembly_status = saveAs;

// The platform replaces these sentinels with a real number on insert. -9999 is
// Manual Input, where the user's typed number stands.
if (saveAs === 'Draft') {
  if (allData.stock_movement_no_type !== -9999 &&
      (!allData.stock_movement_no || allData.stock_movement_no === '')) {
    allData.stock_movement_no = 'draft';
  }
} else {
  if (allData.stock_movement_no_type !== -9999 &&
      (!allData.stock_movement_no || allData.stock_movement_no === '' ||
       storedStatus !== 'Completed')) {
    allData.stock_movement_no = 'issued';
  }
  // Posting to accounting is a separate step (Post button), never part of Complete.
  allData.posted_status = 'Unposted';
}

return { allData: allData, storedStatus: storedStatus };

const entry = {{node:code_fillback.data.allData}};

// Draft needs only what identifies the document. Each recovery row's own
// Storage/Bin, and the stock allocation, are Completed-only checks made in
// Validate Disassembly. The header has no storage/bin columns of its own.
const requiredFields = [
  { name: 'stock_movement_no', label: 'Item Disassembly No' },
  { name: 'issuing_operation_faci', label: 'Plant' },
  { name: 'item_id', label: 'BOM Item Code' },
  { name: 'item_qty', label: 'Disassembly Quantity' },
  { name: 'item_uom', label: 'Quantity UOM' },
  { name: 'item_disassembly_date', label: 'Date' },
  { name: 'stock_movement', label: 'Recovery Components', isArray: true, arrayType: 'object',
    arrayFields: [{ name: 'item_selection', label: 'Item Code' }] }
];

const data = {};
requiredFields.forEach(function (f) { data[f.name] = entry[f.name]; });

return {
  required_fields: JSON.stringify(requiredFields),
  data: JSON.stringify(data)
};

const entry = {{node:code_fillback.data.allData}};

// The source BOM item plus every recovery item, in one fetch.
const ids = [];
if (entry.item_id) ids.push(String(entry.item_id));
(entry.stock_movement || []).forEach(function (line) {
  if (line.item_selection) ids.push(String(line.item_selection));
});

// Typed batch numbers, so Validate Disassembly can reject one that already
// exists. '-' and the auto-generate placeholder are not real numbers. The
// sentinel keeps the lookup from matching everything when nothing was typed.
const batchNumbers = [];
(entry.stock_movement || []).forEach(function (line) {
  const batch = String(line.batch_number || '').trim();
  if (batch && batch !== '-' && batch !== 'Auto-generated batch number' &&
      batchNumbers.indexOf(batch) === -1) {
    batchNumbers.push(batch);
  }
});
if (batchNumbers.length === 0) batchNumbers.push('__no_batch__');

return {
  itemIds: ids.filter(function (v, i, a) { return a.indexOf(v) === i; }),
  batchNumbers: batchNumbers
};

// 8dp is the maximum configurable column precision: rounding COMPUTED values there keeps
// every client-configured scale intact while killing float residue.
const q8 = (v) => Number((parseFloat(v) || 0).toFixed(8));
const entry = {{node:code_fillback.data.allData}};
const storedStatus = {{node:code_fillback.data.storedStatus}};
const items = {{node:search_items.data.data}} || [];
const existingBatches = {{node:search_batches.data.data}} || [];

const itemMap = {};
items.forEach(function (it) { itemMap[String(it.id)] = it; });

let message = '';

// Re-completing a disassembly would move stock a second time.
if (storedStatus === 'Completed') {
  message = 'This Item Disassembly is already Completed and cannot be saved again.';
}

if (!message && !itemMap[String(entry.item_id)]) {
  message = 'The BOM item to disassemble could not be found.';
}

const itemQty = q8(entry.item_qty);
if (!message && itemQty <= 0) {
  message = 'Disassembly quantity must be greater than zero.';
}
if (!message && !entry.item_uom) {
  message = 'Quantity UOM is required.';
}

// --- Source allocation -------------------------------------------------------
let picks = [];
if (!message) {
  try {
    picks = entry.temp_qty_data ? JSON.parse(entry.temp_qty_data) : [];
    if (!Array.isArray(picks)) throw new Error('not an array');
  } catch (e) {
    message = 'The selected stock data is invalid. Select the stock again.';
    picks = [];
  }
}
picks = picks.filter(function (p) { return q8(p.sm_quantity) > 0; });

if (!message && picks.length === 0) {
  message = 'No source stock has been allocated. Select the stock to disassemble.';
}

// temp_qty_data already carries HU picks in balance shape. temp_hu_data is only
// dialog state -- adding it here would count HU stock twice.
if (!message) {
  const allocated = q8(picks.reduce(function (sum, p) {
    return sum + (parseFloat(p.sm_quantity) || 0);
  }, 0));
  if (Math.abs(allocated - itemQty) > 0.00000001) {
    message = 'The allocated stock (' + allocated + ') does not match the disassembly quantity (' +
      itemQty + '). Select the stock again.';
  }
}

const seenSerials = {};
for (let i = 0; i < picks.length && !message; i++) {
  const p = picks[i];
  if (!p.location_id) {
    message = 'Selected stock ' + (i + 1) + ': the bin location is missing. Select the stock again.';
    break;
  }
  const serial = p.serial_number ? String(p.serial_number).trim() : '';
  if (serial) {
    const key = [p.location_id, p.batch_id || '', serial].join('|');
    if (seenSerials[key]) {
      message = 'Serial number ' + serial + ' is selected more than once.';
    }
    seenSerials[key] = true;
  }
}

// --- Recovery components -----------------------------------------------------
const lines = entry.stock_movement || [];
if (!message && lines.length === 0) {
  message = 'There are no recovery components. Add at least one item to recover.';
}

// A typed batch number creates a new batch, so it must not already exist in
// this organization. Within the document, two lines of the same item may
// share one (one batch received into two bins), different items may not.
const existingBatchNumbers = {};
existingBatches.forEach(function (b) {
  existingBatchNumbers[String(b.batch_number).trim()] = true;
});
const batchOwner = {};

for (let i = 0; i < lines.length && !message; i++) {
  const line = lines[i];
  const label = 'Line ' + (i + 1) + ' (' + (line.item_name || line.item_selection || '-') + ')';
  const item = itemMap[String(line.item_selection)];

  if (!line.item_selection) {
    message = label + ': item is required.';
  } else if (!item) {
    message = label + ': the item could not be found.';
  } else if (q8(line.total_quantity) <= 0) {
    message = label + ': quantity must be greater than zero.';
  } else if (!line.quantity_uom) {
    message = label + ': UOM is required.';
  } else if (!line.storage_location_id) {
    message = label + ': storage location is required.';
  } else if (!line.location_id) {
    message = label + ': bin location is required.';
  } else if (item.serial_number_management === 1) {
    // The recovery table has no serial number field yet, so a serial item
    // cannot be received correctly.
    message = label + ': serial-managed items cannot be recovered yet.';
  } else if (item.item_batch_management === 1 &&
             item.batch_number_genaration !== 'According To System Settings') {
    const batch = String(line.batch_number || '').trim();
    if (batch === '' || batch === '-' || batch === 'Auto-generated batch number') {
      message = label + ': Batch number is required.';
    } else if (existingBatchNumbers[batch]) {
      message = label + ': Batch No ' + batch + ' already exists.';
    } else if (batchOwner[batch] && batchOwner[batch] !== String(line.item_selection)) {
      message = label + ': Batch No ' + batch + ' is already used by another item in this document.';
    } else {
      batchOwner[batch] = String(line.item_selection);
    }
  }
}

return { status: message ? 'Failed' : 'Passed', message: message };

const raw = {{node:get_persisted_ida.data.data}};

// Read the stored status from the DB, never from allData: a stale tab or a
// double-click posts the pre-completion status and would move stock twice.
const rec = Array.isArray(raw) ? raw[0] : raw;
const status = rec ? rec.item_disassembly_status : '';
const blocked = status === 'Completed' || status === 'Fully Posted' ? 1 : 0;

return {
  blocked: blocked,
  blockedMessage: blocked === 1
    ? 'This Item Disassembly is already ' + status + ' and cannot be saved again.'
    : ''
};

const entry = {{node:code_fillback.data.allData}};
// Every source pick is checked before the first write, so a shortfall on any
// pick stops the save while nothing has moved yet.
let picks = [];
try {
  picks = entry.temp_qty_data ? JSON.parse(entry.temp_qty_data) : [];
} catch (e) {
  picks = [];
}

return {
  plant_id: entry.issuing_operation_faci,
  organization_id: entry.organization_id,
  material_id: entry.item_id,
  material_uom: entry.item_uom,
  balancesToProcess: picks.filter(function (p) {
    return (parseFloat(p.sm_quantity) || 0) > 0;
  })
};

const pick = {{node:loop_precheck_picks}};

return {
  location_id: pick.location_id || null,
  batch_id: pick.batch_id || null,
  quantity: parseFloat(pick.sm_quantity) || 0,
  inventory_category: pick.category || 'Unrestricted'
};

const entry = {{node:code_fillback.data.allData}};
const items = {{node:search_items.data.data}} || [];
const userId = {{system:uid}};

const itemMap = {};
items.forEach(function (it) { itemMap[String(it.id)] = it; });

// Only rows whose item numbers batches automatically, and that still hold the
// form's placeholder, need a real number before stock can be received.
const genLines = [];
(entry.stock_movement || []).forEach(function (line, index) {
  const item = itemMap[String(line.item_selection)] || {};
  const batch = String(line.batch_number || '');
  if (item.item_batch_management === 1 &&
      item.batch_number_genaration === 'According To System Settings' &&
      (batch === '' || batch === 'Auto-generated batch number')) {
    genLines.push({
      index: index,
      item_id: String(line.item_selection),
      document_date: entry.item_disassembly_date || null,
      manufacturing_date: line.manufacturing_date || null,
      expired_date: line.expired_date || null
    });
  }
});

return {
  genLines: genLines,
  genCount: genLines.length,
  // Cache keys are global, so each run gets its own.
  cacheKey: String(userId || '') + '_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8)
};

const line = {{node:loop_gen_batch}};

return {
  index: line.index,
  item_id: line.item_id,
  document_date: line.document_date || null,
  manufacturing_date: line.manufacturing_date || null,
  expired_date: line.expired_date || null
};

const raw = {{node:wf_generate_batch.data}};
const batchNumber = raw && raw.batch_number ? String(raw.batch_number) : '';
const itemId = {{node:code_gen_pick.data.item_id}};

return {
  batchNumber: batchNumber,
  isError: batchNumber === '' ? 1 : 0,
  message: batchNumber === ''
    ? 'Could not generate a batch number for item ' + itemId + '. Check the Batch Number Configuration for this item.'
    : ''
};

const cachedRaw = {{node:get_batches.data}};
const arr = Array.isArray(cachedRaw) ? cachedRaw : (cachedRaw ? JSON.parse(cachedRaw) : []);

arr.push({
  index: {{node:code_gen_pick.data.index}},
  batch_number: {{node:code_normalize_batch.data.batchNumber}}
});

return { generatedBatches: arr };

const entry = {{node:code_fillback.data.allData}};
const genCount = {{node:code_batch_plan.data.genCount}};
// Lives inside if_needs_batch_gen, so it is null whenever generation was skipped.
const raw = {{node:get_batches_final.data}};

const generated = genCount > 0
  ? (Array.isArray(raw) ? raw : (raw ? JSON.parse(raw) : []))
  : [];

const genMap = {};
generated.forEach(function (g) { genMap[g.index] = g.batch_number; });

const lines = (entry.stock_movement || []).map(function (line, index) {
  const copy = Object.assign({}, line);
  if (genMap[index]) copy.batch_number = genMap[index];
  return copy;
});

return { stock_movement: lines };

const pageStatus = {{workflowparams:pageStatus}};
const updated = {{node:get_ida.data.data}};
const added = {{node:add_ida.data}};

// One of these two ran; the other resolves null. Guarded on pageStatus.
let rec = pageStatus === 'Edit' ? updated : added;
if (Array.isArray(rec)) rec = rec[0];
rec = rec || {};

// The serial engine replaced the 'issued' sentinel during the write, so this is
// the first point the REAL document number exists. Everything downstream stamps
// trx_no from here -- stamping it from the fillback copy would write the literal
// string 'issued' onto every inventory movement.
return {
  docId: rec.id ? String(rec.id) : '',
  stock_movement_no: rec.stock_movement_no || ''
};

const entry = {{node:code_fillback.data.allData}};
const persisted = {{node:code_persisted.data}};
const items = {{node:search_items.data.data}} || [];

let picks = [];
try {
  picks = entry.temp_qty_data ? JSON.parse(entry.temp_qty_data) : [];
} catch (e) {
  picks = [];
}

const itemData = items.find(function (it) {
  return String(it.id) === String(entry.item_id);
}) || null;

return {
  plant_id: entry.issuing_operation_faci,
  organization_id: entry.organization_id,
  stock_movement_no: persisted.stock_movement_no,
  doc_date: entry.item_disassembly_date || null,
  material_id: entry.item_id,
  material_uom: entry.item_uom,
  itemData: itemData,
  balancesToProcess: picks.filter(function (p) {
    return (parseFloat(p.sm_quantity) || 0) > 0;
  })
};

const pick = {{node:loop_issue_picks}};

// Every nullable param is null, never '': SUBTRACT_INVENTORY's own Batch ID node
// does `const batchId = ...; if (batchId === "") batchId = null`, which throws
// TypeError: Assignment to constant. MSI passes null for the same reason.
return {
  location_id: pick.location_id || null,
  batch_id: pick.batch_id || null,
  quantity: parseFloat(pick.sm_quantity) || 0,
  inventory_category: pick.category || 'Unrestricted',
  manufacturing_date: pick.manufacturing_date || null,
  expired_date: pick.expired_date || null,
  handling_unit_id: pick.handling_unit_id || null
};

// 8dp is the maximum configurable column precision: rounding COMPUTED values there keeps
// every client-configured scale intact while killing float residue.
const q8 = (v) => Number((parseFloat(v) || 0).toFixed(8));
const entry = {{node:code_fillback.data.allData}};
const items = {{node:search_items.data.data}} || [];
const movements = {{node:search_movements.data.data}} || [];
const persisted = {{node:code_persisted.data}};
const lines = {{node:code_apply_batches.data.stock_movement}} || [];

const itemMap = {};
items.forEach(function (it) { itemMap[String(it.id)] = it; });

// Read the issued value back off the movements the issue leg just wrote.
// SUBTRACT has a success path that returns only `code` and no unit_price, so its
// response can never be relied on; the movement rows always carry the real figure.
const issuedValue = movements.reduce(function (sum, m) {
  return sum + (parseFloat(m.total_price) || 0);
}, 0);

// PROVISIONAL COSTING RULE -- Finance has not confirmed the policy yet.
// The issued value is split across recovery lines by each line's share of the
// total recovered quantity, so recovered value always equals issued value and no
// variance is posted. The last line takes the rounding remainder. Replace this
// block once the costing policy is decided.
const totalQty = lines.reduce(function (sum, l) { return sum + q8(l.total_quantity); }, 0);
let remaining = issuedValue;

const receipts = lines.map(function (line, i) {
  const qty = q8(line.total_quantity);
  const lineValue = i === lines.length - 1
    ? remaining
    : (totalQty > 0 ? issuedValue * qty / totalQty : 0);
  remaining -= lineValue;

  // '-' is the form's "no batch" marker, not a batch number.
  const batch = String(line.batch_number || '');

  return {
    plant_id: line.issuing_plant || entry.issuing_operation_faci,
    organization_id: line.organization_id || entry.organization_id,
    material_id: line.item_selection,
    material_uom: line.quantity_uom,
    quantity: qty,
    unit_price: qty > 0 ? q8(lineValue / qty) : 0,
    location_id: line.location_id,
    batch_number: batch === '-' ? '' : batch,
    trx_no: persisted.stock_movement_no,
    doc_date: entry.item_disassembly_date || null,
    manufacturing_date: line.manufacturing_date || null,
    expired_date: line.expired_date || null,
    remark: line.item_remark || '',
    remark2: line.item_remark_2 || '',
    remark3: line.item_remark_3 || '',
    itemData: itemMap[String(line.item_selection)] || null
  };
});

return { receipts: receipts, issuedValue: q8(issuedValue) };

const entry = {{node:code_fillback.data.allData}};

// Source stock picked out of a handling unit has to be unloaded from it.
let picks = [];
try {
  picks = entry.temp_qty_data ? JSON.parse(entry.temp_qty_data) : [];
} catch (e) {
  picks = [];
}

const byHu = {};
picks.forEach(function (p) {
  if (!p.handling_unit_id) return;
  if ((parseFloat(p.sm_quantity) || 0) <= 0) return;
  const key = String(p.handling_unit_id);
  if (!byHu[key]) {
    byHu[key] = {
      handling_unit_id: key,
      plant_id: entry.issuing_operation_faci,
      organization_id: entry.organization_id,
      location_id: p.location_id || null,
      storage_location_id: p.storage_location_id || null,
      table_hu_items: []
    };
  }
  byHu[key].table_hu_items.push({
    material_id: p.material_id || entry.item_id,
    location_id: p.location_id || null,
    batch_id: p.batch_id || null,
    material_uom: entry.item_uom,
    quantity: parseFloat(p.sm_quantity) || 0,
    balance_id: p.balance_id || null
  });
});

const huUpdates = Object.keys(byHu).map(function (k) { return byHu[k]; });

return { huUpdates: huUpdates, huUpdatesLength: huUpdates.length };

const hu = {{node:loop_hu}};

return {
  handling_unit_id: hu.handling_unit_id,
  plant_id: hu.plant_id,
  organization_id: hu.organization_id,
  location_id: hu.location_id,
  storage_location_id: hu.storage_location_id,
  table_hu_items: hu.table_hu_items
};

const entry = {{node:code_fillback.data.allData}};

const ids = [];
if (entry.item_id) ids.push(String(entry.item_id));
(entry.stock_movement || []).forEach(function (line) {
  if (line.item_selection) ids.push(String(line.item_selection));
});

const stamp = new Date().toISOString();

const updates = [];
ids.filter(function (v, i, a) { return a.indexOf(v) === i; }).forEach(function (id) {
  updates.push({ id: id, last_transaction_date: stamp });
});

return { updates: updates };

const entry = {{node:code_fillback.data.allData}};
const persisted = {{node:code_persisted.data.docId}};
// Each add-node lives in a mutually exclusive branch, so at most one of these
// resolves; the others come back null.
const addedDraft = {{node:add_draft.data}};

const firstId = function (raw) {
  if (!raw) return '';
  const row = raw.length > 0 ? raw[0] : raw;
  return row && row.id ? String(row.id) : '';
};

return { id: String(persisted || '') || firstId(addedDraft) || String(entry.id || '') };
